//! Independent synthetic source-to-canonical oracles. Expected values are fixed
//! arithmetic fixtures, never generated by the normalizer or profile compiler.
use super::{TestResult, assertions, root, runtime::TestRun};
use arrow_array::{Array, BooleanArray, Decimal256Array, Int64Array, StringArray};
use marketforge_engine::historical::{
    config::PreparedBatch,
    normalize::{ProcessingStatus, execute_processing_job},
};
use rust_decimal::Decimal;
use serde_json::json;
use std::{fs, io::Write, sync::Mutex};
static PROFILE_EXECUTION: Mutex<()> = Mutex::new(());
#[derive(Debug, Clone, Copy)]
pub enum Units {
    Base,
    Quote,
    LinearHundredth,
    LinearTenThousandth,
    InverseHundred,
    InverseOne,
}
impl Units {
    fn metadata(self) -> (Option<&'static str>, Option<&'static str>) {
        match self {
            Self::LinearHundredth => (Some("0.01"), Some("BTC")),
            Self::LinearTenThousandth => (Some("0.0001"), Some("BTC")),
            Self::InverseHundred => (Some("100"), Some("USD")),
            Self::InverseOne => (Some("1"), Some("USD")),
            _ => (None, None),
        }
    }
    fn expected(self, trade: bool) -> (&'static str, &'static str, Option<&'static str>) {
        match (self, trade) {
            (Self::Base, true) => ("3", "600", None),
            (Self::Base, false) => ("2", "400", None),
            (Self::Quote, true) => ("0.015", "3", None),
            (Self::Quote, false) => ("0.01", "2", None),
            (Self::LinearHundredth, true) => ("0.03", "6", Some("3")),
            (Self::LinearHundredth, false) => ("0.02", "4", Some("2")),
            (Self::LinearTenThousandth, true) => ("0.0003", "0.06", Some("3")),
            (Self::LinearTenThousandth, false) => ("0.0002", "0.04", Some("2")),
            (Self::InverseHundred, true) => ("1.5", "300", Some("3")),
            (Self::InverseHundred, false) => ("1", "200", Some("2")),
            (Self::InverseOne, true) => ("0.015", "3", Some("3")),
            (Self::InverseOne, false) => ("0.01", "2", Some("2")),
        }
    }
}
/// Persisted explicit unit namespace: trade/depth for the same full identity use
/// the same ID. New identities append IDs; do not renumber this mapping.
pub(super) fn identity(exchange: &str, kind: &str, category: &str) -> (i64, &'static str) {
    match (exchange, kind, category) {
        ("binance", "spot", "spot") => (1, "BTCUSDT"),
        ("binance", "perpetual", "linear") => (2, "BTCUSDT"),
        ("binance", "perpetual", "inverse") => (3, "BTCUSD_PERP"),
        ("binance", "future", "linear") => (4, "BTCUSDT_261225"),
        ("binance", "future", "inverse") => (5, "BTCUSD_261225"),
        ("bitget", "spot", "spot") => (6, "BTCUSDT"),
        ("bitget", "perpetual", "linear") => (7, "BTCUSDT"),
        ("bybit", "spot", "spot") => (8, "BTCUSDT"),
        ("bybit", "perpetual", "linear") => (9, "BTCUSDT"),
        ("bybit", "perpetual", "inverse") => (10, "BTCUSD"),
        ("bybit", "future", "linear") => (11, "BTCUSDT-25DEC26"),
        ("gateio", "spot", "spot") => (12, "BTC_USDT"),
        ("gateio", "perpetual", "linear") => (13, "BTC_USDT"),
        ("gateio", "perpetual", "inverse") => (14, "BTC_USD"),
        ("okx", "spot", "spot") => (15, "BTC-USDT"),
        ("okx", "perpetual", "linear") => (16, "BTC-USDT-SWAP"),
        ("okx", "perpetual", "inverse") => (17, "BTC-USD-SWAP"),
        ("okx", "future", "linear") => (18, "BTC-USD_UM-261225"),
        ("okx", "future", "inverse") => (19, "BTC-USD-261225"),
        ("xnas", "equity", "equity") => (20, "AAPL"),
        _ => panic!("undeclared unit identity"),
    }
}
fn wrap(path: &std::path::Path, container: &str, bytes: &[u8]) -> TestResult<()> {
    let f = fs::File::create(path).map_err(|e| e.to_string())?;
    match container {
        "plain" => (&f).write_all(bytes).map_err(|e| e.to_string())?,
        "gzip" => {
            let mut e = flate2::write::GzEncoder::new(f, flate2::Compression::default());
            e.write_all(bytes).map_err(|e| e.to_string())?;
            e.finish().map_err(|e| e.to_string())?;
        }
        "zip" => {
            let mut z = zip::ZipWriter::new(f);
            z.start_file("sample.data", zip::write::SimpleFileOptions::default())
                .map_err(|e| e.to_string())?;
            z.write_all(bytes).map_err(|e| e.to_string())?;
            z.finish().map_err(|e| e.to_string())?;
        }
        "tar_gzip" => {
            let e = flate2::write::GzEncoder::new(f, flate2::Compression::default());
            let mut tar = tar::Builder::new(e);
            let mut h = tar::Header::new_gnu();
            h.set_size(bytes.len() as u64);
            h.set_mode(0o644);
            h.set_cksum();
            tar.append_data(&mut h, "sample.data", bytes)
                .map_err(|e| e.to_string())?;
            tar.into_inner()
                .map_err(|e| e.to_string())?
                .finish()
                .map_err(|e| e.to_string())?;
        }
        _ => return Err("undeclared wrapper".into()),
    };
    Ok(())
}
fn source(
    exchange: &str,
    kind: &str,
    category: &str,
    symbol: &str,
    trade: bool,
) -> (String, Vec<u8>) {
    if trade {
        let (container, text) = match exchange {
            "binance" if kind == "spot" => ("zip", "7,200,3,600,1250000,False,True\n".into()),
            "binance" => (
                "zip",
                format!(
                    "id,price,qty,{},time,is_buyer_maker\n7,200,3,600,1250,false\n",
                    if category == "inverse" {
                        "base_qty"
                    } else {
                        "quote_qty"
                    }
                ),
            ),
            "bitget" => (
                "zip",
                "trade_id,timestamp,price,side,volume(quote),size(base)\n7,1250,200,buy,600,3\n"
                    .into(),
            ),
            "bybit" if kind == "spot" => (
                "gzip",
                "id,timestamp,price,volume,side,rpi\n7,1250,200,3,buy,1\n".into(),
            ),
            "bybit" => (
                "gzip",
                format!(
                    "timestamp,symbol,side,size,price,tickDirection,trdMatchID,grossValue,homeNotional,foreignNotional,RPI\n1.25,{symbol},Buy,3,200,PlusTick,7,0,3,600,1\n"
                ),
            ),
            "gateio" if kind == "spot" => ("gzip", "1.25,7,200,3,2\n".into()),
            "gateio" => ("gzip", "1.25,7,200,3\n".into()),
            "okx" => (
                "zip",
                format!(
                    "instrument_name,trade_id,side,price,size,created_time,source\n{symbol},7,buy,200,3,1250,1\n"
                ),
            ),
            "xnas" => (
                "plain",
                format!(
                    "{}\n",
                    json!({
                        "hd": {"ts_event": "1970-01-01T00:00:01.250000000Z"},
                        "ts_recv": "1970-01-01T00:00:01.260000000Z", "symbol": symbol,
                        "price": "200", "size": 3, "side": "b", "sequence": 7,
                    })
                ),
            ),
            _ => panic!("unknown exchange"),
        };
        return (container.into(), text.into_bytes());
    }
    match exchange {
        "bybit" => {
            let a = json!({"type":"snapshot","ts":1250,"cts":1250,"data":{"s":symbol,"u":10,"b":[["200","2"]],"a":[["400","3"]]}});
            let b = json!({"type":"delta","ts":1500,"cts":1500,"data":{"s":symbol,"u":11,"b":[["200","0"]],"a":[]}});
            ("zip".into(), format!("{a}\n{b}\n").into_bytes())
        }
        "okx" => {
            let a = json!({"instId":symbol,"action":"snapshot","ts":"1250","bids":[["200","2","1"]],"asks":[["400","3","2"]]});
            let b = json!({"instId":symbol,"action":"update","ts":"1500","bids":[["200","0","0"]],"asks":[]});
            ("tar_gzip".into(), format!("{a}\n{b}\n").into_bytes())
        }
        "gateio" if kind == "spot" => (
            "gzip".into(),
            b"1.25,2,set,200,2,10,0\n1.25,1,set,400,3,10,0\n1.5,2,make,200,1,11,1\n".to_vec(),
        ),
        "gateio" => (
            "gzip".into(),
            format!(
                "{}\n",
                json!({"update":1.25,"bids":[{"p":"200","s":2}],"asks":[{"p":"400","s":3}]})
            )
            .into_bytes(),
        ),
        "bitget" => {
            let xml = r#"<worksheet><sheetData><row r="1"><c r="A1" t="inlineStr"><is><t>timestamp</t></is></c><c r="B1" t="inlineStr"><is><t>asks</t></is></c><c r="C1" t="inlineStr"><is><t>bids</t></is></c></row><row r="2"><c r="A2"><v>2</v></c><c r="B2" t="inlineStr"><is><t>[[400,3]]</t></is></c><c r="C2" t="inlineStr"><is><t>[[200,3]]</t></is></c></row><row r="3"><c r="A3"><v>1</v></c><c r="B3" t="inlineStr"><is><t>[[400,3]]</t></is></c><c r="C3" t="inlineStr"><is><t>[[200,2]]</t></is></c></row></sheetData></worksheet>"#;
            let mut z = zip::ZipWriter::new(std::io::Cursor::new(vec![]));
            z.start_file(
                "xl/worksheets/sheet1.xml",
                zip::write::SimpleFileOptions::default(),
            )
            .unwrap();
            z.write_all(xml.as_bytes()).unwrap();
            ("zip".into(), z.finish().unwrap().into_inner())
        }
        "xnas" => (
            "plain".into(),
            format!("{}\n", json!({
                "hd": {"ts_event": "1970-01-01T00:00:01.250000000Z"},
                "ts_recv": "1970-01-01T00:00:01.260000000Z", "symbol": symbol, "sequence": 7,
                "levels": [{"bid_px":"200","bid_sz":2,"bid_ct":1,"ask_px":"400","ask_sz":3,"ask_ct":1}],
            })).into_bytes(),
        ),
        _ => panic!("unknown depth format"),
    }
}
fn decimal(batch: &arrow_array::RecordBatch, name: &str, row: usize) -> Option<Decimal> {
    let a = batch
        .column_by_name(name)
        .unwrap()
        .as_any()
        .downcast_ref::<Decimal256Array>()
        .unwrap();
    (!a.is_null(row)).then(|| {
        marketforge_engine::shared::persistence::parquet::i256_to_decimal(a.value(row)).unwrap()
    })
}
fn text<'a>(batch: &'a arrow_array::RecordBatch, name: &str, row: usize) -> Option<&'a str> {
    let a = batch
        .column_by_name(name)
        .unwrap()
        .as_any()
        .downcast_ref::<StringArray>()
        .unwrap();
    (!a.is_null(row)).then(|| a.value(row))
}
pub fn synthetic(id: &str, units: Units) -> TestResult<()> {
    let _serial = PROFILE_EXECUTION.lock().map_err(|e| e.to_string())?;
    let parts: Vec<_> = id.split('.').collect();
    let [exchange, kind, category, data_type] = parts.as_slice() else {
        return Err("bad case identity".into());
    };
    let (instrument_id, symbol) = identity(exchange, kind, category);
    let trade = *data_type == "trades";
    let (value, asset) = units.metadata();
    let (container, bytes) = source(exchange, kind, category, symbol, trade);
    let mut run = TestRun::new(&format!("exchanges/{exchange}/{}", id.replace('.', "_")))?;
    let result = (|| {
        let path = run.path.join("synthetic.source");
        wrap(&path, &container, &bytes)?;
        let mut task = json!({"task_id":1,"input_path":path,"exchange":exchange,"instrument_type":kind,"market_category":category,"symbol":symbol,"base_asset":if *kind=="equity"{symbol}else{"BTC"},"quote_asset":if matches!(*category,"inverse"|"equity"){"USD"}else{"USDT"},"instrument_id":instrument_id,"instrument":{"tick_size":"0.1","contract_value":value,"contract_value_asset":asset},"stream_id":format!("unit.{exchange}.{kind}.{category}.{symbol}"),"stream_rank":1});
        if *exchange == "gateio" && !trade {
            task["source_options"] =
                json!({"feed":if *kind=="spot"{"incremental"}else{"snapshot"}});
        }
        let entry = json!({"instrument_id":instrument_id,"exchange":exchange,"instrument_type":kind,"market_category":category,"symbol":symbol,"base_asset":task["base_asset"],"quote_asset":task["quote_asset"],"instrument":task["instrument"]});
        let b:PreparedBatch=serde_json::from_value(json!({"schema_version":4,"kind":"normalization_batch","status":"prepared","run_id":"synthetic-profile-case","run_directory":"unit-run","batch_path":"unit-batch","ranking_policy":"turnover","ranking_snapshot":null,"requested_interval":{"start":"1970-01-01T00:00:00Z","end":"1970-01-02T00:00:00Z"},"instrument_namespace":"marketforge-profile-unit-v1","instruments":[entry],"jobs":[{"operation":"normalize","job_id":1,"dataset_id":1,"tasks":[task],"ordering":{"primary":"event_timestamp_ns","tie_break":"stream_rank"},"output":{"content_type":data_type,"staging_path":"unit-staging","dataset_path":"unit-dataset"}}]})).map_err(|e|e.to_string())?;
        let c = run.runtime_from_general()?;
        let resolved = run.prepare(&b, &c)?;
        let job = &resolved.jobs[0];
        if job.tasks[0].raw_schema["marketforge_profile"]["id"] != id {
            return Err("wrong production profile".into());
        }
        let r = execute_processing_job(job, &c).map_err(|e| e.to_string())?;
        if r.status != ProcessingStatus::Complete {
            return Err(format!("{id}: {r:?}"));
        }
        let m = assertions::committed(&run, &b.jobs[0], &r)?;
        let catalog = marketforge_engine::historical::config::FormatCatalog::load(
            root().join("data/.config/engine/normalize"),
        )
        .map_err(|e| e.to_string())?;
        let reloaded = marketforge_engine::historical::config::load_document_with_catalog(
            job.output.dataset_path.join("processing-job.json"),
            &catalog,
        )
        .map_err(|e| e.to_string())?;
        // The catalog loader intentionally normalizes legacy source metadata.
        // Verify the exact committed provenance independently of that transformation.
        let saved_bytes = fs::read(job.output.dataset_path.join("processing-job.json"))
            .map_err(|e| e.to_string())?;
        let saved: marketforge_engine::historical::job::ProcessingJob =
            serde_json::from_slice(&saved_bytes).map_err(|e| e.to_string())?;

        if saved.tasks != job.tasks {
            return Err(format!("{id}: committed provenance changed tasks"));
        }

        // Also ensure the compatibility loader accepts the committed snapshot.
        if reloaded.tasks.len() != job.tasks.len() {
            return Err(format!("{id}: provenance reload changed task count"));
        }
        let expected_rows = if trade {
            1
        } else if *exchange == "xnas" || (*exchange == "gateio" && *kind != "spot") {
            2
        } else {
            3
        };
        if m.events_written != expected_rows {
            return Err(format!(
                "{id}: expected {expected_rows} rows, got {}",
                m.events_written
            ));
        }
        let expected_time = if *exchange == "bitget" && !trade {
            1_000_000_000
        } else {
            1_250_000_000
        };
        let expected = units.expected(trade);
        let mut found = false;
        let mut final_book = std::collections::BTreeMap::new();
        for file in &m.files {
            let reader = parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder::try_new(
                fs::File::open(job.output.dataset_path.join(&file.path))
                    .map_err(|e| e.to_string())?,
            )
            .map_err(|e| e.to_string())?
            .build()
            .map_err(|e| e.to_string())?;
            for batch in reader {
                let batch = batch.map_err(|e| e.to_string())?;
                let timestamps = batch
                    .column_by_name("event_timestamp_ns")
                    .unwrap()
                    .as_any()
                    .downcast_ref::<Int64Array>()
                    .unwrap();
                let ids = batch
                    .column_by_name("instrument_id")
                    .unwrap()
                    .as_any()
                    .downcast_ref::<Int64Array>()
                    .unwrap();
                for row in 0..batch.num_rows() {
                    if ids.value(row) != instrument_id
                        || text(&batch, "exchange", row) != Some(exchange)
                        || text(&batch, "symbol", row) != Some(symbol)
                    {
                        return Err(format!("{id}: incorrect canonical identity"));
                    }
                    let price = decimal(&batch, "price", row).unwrap();
                    let base = decimal(&batch, "quantity_base", row);
                    let quote = decimal(&batch, "quantity_quote", row);
                    let contracts = decimal(&batch, "quantity_contracts", row);
                    let side = text(&batch, "side", row).unwrap();
                    if timestamps.value(row) == expected_time
                        && price == Decimal::from(200)
                        && side == if trade { "buy" } else { "bid" }
                    {
                        if base != Some(expected.0.parse().unwrap())
                            || quote != Some(expected.1.parse().unwrap())
                            || contracts != expected.2.map(|s| s.parse().unwrap())
                        {
                            return Err(format!(
                                "{id}: quantity mismatch {base:?}/{quote:?}/{contracts:?}, expected {expected:?}"
                            ));
                        }
                        if trade {
                            let expected_id = (*exchange != "xnas").then_some("7");
                            if text(&batch, "trade_id", row) != expected_id {
                                return Err("trade ID mismatch".into());
                            }
                            let a = batch
                                .column_by_name("is_rpi")
                                .unwrap()
                                .as_any()
                                .downcast_ref::<BooleanArray>()
                                .unwrap();
                            let actual = (!a.is_null(row)).then(|| a.value(row));
                            let expected_rpi = if *exchange == "bybit" || *exchange == "okx" {
                                Some(true)
                            } else {
                                None
                            };
                            if actual != expected_rpi {
                                return Err(format!("{id}: RPI mismatch"));
                            }
                        }
                        found = true;
                    }
                    if !trade {
                        let native = match units {
                            Units::Base => base,
                            Units::Quote => quote,
                            _ => contracts,
                        }
                        .ok_or("missing native quantity")?;
                        let key = (side.to_string(), price);
                        if native.is_zero() {
                            final_book.remove(&key);
                        } else {
                            final_book.insert(key, native);
                        }
                    }
                }
            }
        }
        if !found {
            return Err(format!(
                "{id}: missing independently expected initial canonical row"
            ));
        }
        if !trade {
            let bid = final_book.get(&("bid".into(), 200.into())).copied();
            let expected_bid = if *exchange == "bybit" || *exchange == "okx" {
                None
            } else if *exchange == "bitget" || *kind == "spot" {
                Some(3.into())
            } else {
                Some(2.into())
            };
            if bid != expected_bid {
                return Err(format!(
                    "{id}: wrong independently expected final bid state"
                ));
            }
        }
        Ok(())
    })();
    run.finish(&result)?;
    result
}

/// Bounded independent archive oracle; source files remain read-only.
#[cfg(feature = "historical-real-tests")]
pub fn binance_linear_prefix() -> TestResult<()> {
    use super::fixtures::{profile_source, workload};
    use marketforge_engine::{
        historical::job::{ContentType, InstrumentKind},
        shared::domain::canonical::Exchange,
    };
    let b = workload()?;
    let mut b = profile_source(
        &b,
        Exchange::Binance,
        InstrumentKind::Perpetual,
        "linear",
        ContentType::Trades,
        None,
        false,
    )?;
    b.jobs[0].tasks.truncate(1);
    let mut run = TestRun::new("exchanges/binance/perpetual_linear_archive_prefix")?;
    let result = (|| {
        super::runtime::sample_prefix(&mut run, &mut b, 2)?;
        let config = run.runtime_from_general()?;
        let resolved = run.prepare(&b, &config)?;
        let raw = super::runtime::sample_bytes(&resolved.jobs[0].tasks[0])?;
        let mut csv = csv::Reader::from_reader(raw.as_slice());
        let headers = csv.headers().map_err(|e| e.to_string())?.clone();
        let row = csv
            .records()
            .next()
            .ok_or("missing sampled trade")?
            .map_err(|e| e.to_string())?;
        let field = |name| {
            row.get(headers.iter().position(|h| h == name).unwrap())
                .unwrap()
        };
        let expected_id = field("id");
        let expected_timestamp = field("time")
            .parse::<i64>()
            .map_err(|e| e.to_string())?
            .checked_mul(1_000_000)
            .ok_or("timestamp overflow")?;
        let expected_price: Decimal = field("price").parse().map_err(|e| format!("{e}"))?;
        let expected_base: Decimal = field("qty").parse().map_err(|e| format!("{e}"))?;
        let expected_side = match field("is_buyer_maker") {
            "true" => "sell",
            "false" => "buy",
            _ => return Err("invalid maker flag".into()),
        };
        let results = resolved
            .jobs
            .iter()
            .map(|job| execute_processing_job(job, &config).map_err(|e| e.to_string()))
            .collect::<Result<Vec<_>, String>>()?;
        let manifest = assertions::committed(&run, &b.jobs[0], &results[0])?;
        if manifest.events_written != 1 {
            return Err("expected one source trade".into());
        }
        let dataset = std::path::Path::new(results[0].manifest_path.as_ref().unwrap())
            .parent()
            .unwrap();
        let reader = parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder::try_new(
            fs::File::open(dataset.join(&manifest.files[0].path)).map_err(|e| e.to_string())?,
        )
        .map_err(|e| e.to_string())?
        .build()
        .map_err(|e| e.to_string())?;
        let batch = reader
            .into_iter()
            .next()
            .ok_or("missing canonical row")?
            .map_err(|e| e.to_string())?;
        let d = |name: &str| {
            let a = batch
                .column_by_name(name)
                .unwrap()
                .as_any()
                .downcast_ref::<Decimal256Array>()
                .unwrap();
            marketforge_engine::shared::persistence::parquet::i256_to_decimal(a.value(0)).unwrap()
        };
        let timestamp = batch
            .column_by_name("event_timestamp_ns")
            .unwrap()
            .as_any()
            .downcast_ref::<Int64Array>()
            .unwrap()
            .value(0);
        if timestamp != expected_timestamp
            || text(&batch, "trade_id", 0) != Some(expected_id)
            || text(&batch, "side", 0) != Some(expected_side)
            || d("price") != expected_price
            || d("quantity_base") != expected_base
            || d("quantity_quote") != expected_price * expected_base
        {
            return Err("Binance sampled first trade differs from independent CSV oracle".into());
        }
        Ok(())
    })();
    run.finish(&result)?;
    result
}

/// Run the exact downloadable authoring examples through the production catalogue and reader.
pub fn authoring_examples() -> TestResult<()> {
    use marketforge_engine::historical::config::FormatCatalog;
    use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;

    let _serial = PROFILE_EXECUTION.lock().map_err(|e| e.to_string())?;
    let examples = root().join("docs/content/examples/catalogue");
    let mut run = TestRun::new("profiles/authoring_examples")?;
    let result = (|| {
        let catalogue_root = run.path.join("catalogue");
        let mut inputs = vec![];
        for (kind, file) in [
            ("trades", "synthetic-trades.csv"),
            ("depth", "synthetic-depth.jsonl"),
        ] {
            let directory = catalogue_root.join("profiles").join(kind);
            fs::create_dir_all(&directory).map_err(|e| e.to_string())?;
            let profile = format!("example_exchange.equity.equity.{kind}.toml");
            let source = if kind == "depth" {
                examples.join("incremental")
            } else {
                examples.clone()
            };
            fs::copy(source.join(&profile), directory.join(profile)).map_err(|e| e.to_string())?;
            let fixture = run.path.join(file);
            fs::copy(source.join(file), &fixture).map_err(|e| e.to_string())?;
            inputs.push((kind, fixture));
        }
        let catalogue = FormatCatalog::load(catalogue_root).map_err(|e| e.to_string())?;
        for (index, (kind, fixture)) in inputs.into_iter().enumerate() {
            let number = index + 1;
            let instrument = json!({
                "instrument_id": 1, "exchange": "example_exchange", "instrument_type": "equity",
                "market_category": "equity", "symbol": "AAPL", "base_asset": "AAPL",
                "quote_asset": "USD", "instrument": {"tick_size": "0.01"}
            });
            let mut task = instrument.clone();
            task["task_id"] = json!(number);
            task["input_path"] = json!(fixture);
            task["stream_id"] = json!("examples.equity.AAPL");
            task["stream_rank"] = json!(1);
            let batch: PreparedBatch = serde_json::from_value(json!({
                "schema_version": 4, "kind": "normalization_batch", "status": "prepared",
                "run_id": "authoring-example", "run_directory": "fixture", "batch_path": "fixture",
                "ranking_policy": "turnover", "ranking_snapshot": null,
                "requested_interval": {"start": "2024-10-28T00:00:00Z", "end": "2024-10-29T00:00:00Z"},
                "instrument_namespace": "marketforge-profile-example", "instruments": [instrument],
                "jobs": [{"operation": "normalize", "job_id": number, "dataset_id": number,
                    "tasks": [task], "ordering": {"primary": "event_timestamp_ns", "tie_break": "stream_rank"},
                    "output": {"content_type": kind, "staging_path": "fixture", "dataset_path": "fixture"}}]
            })).map_err(|e| e.to_string())?;
            let runtime = run.runtime_from_general()?;
            let resolved = run.prepare_with_catalogue(&batch, &runtime, &catalogue)?;
            let job = &resolved.jobs[0];
            let output = execute_processing_job(job, &runtime).map_err(|e| e.to_string())?;
            if output.status != ProcessingStatus::Complete {
                return Err(format!("{kind}: {output:?}"));
            }
            let manifest = assertions::committed(&run, &batch.jobs[0], &output)?;
            let mut rows = vec![];
            for file in manifest.files {
                let source = fs::File::open(job.output.dataset_path.join(file.path))
                    .map_err(|e| e.to_string())?;
                let reader = ParquetRecordBatchReaderBuilder::try_new(source)
                    .and_then(|builder| builder.build())
                    .map_err(|e| e.to_string())?;
                for batch in reader {
                    let batch = batch.map_err(|e| e.to_string())?;
                    let time = batch
                        .column_by_name("event_timestamp_ns")
                        .unwrap()
                        .as_any()
                        .downcast_ref::<Int64Array>()
                        .unwrap();
                    for row in 0..batch.num_rows() {
                        rows.push((
                            time.value(row),
                            text(&batch, "side", row).unwrap().to_owned(),
                            decimal(&batch, "price", row).unwrap(),
                            decimal(&batch, "quantity_base", row).unwrap(),
                            decimal(&batch, "quantity_quote", row).unwrap(),
                        ));
                    }
                }
            }
            const START: i64 = 1_730_125_800_000_000_000;
            let expected = if kind == "trades" {
                vec![(START, "buy", "233.62", "10", "2336.20")]
            } else {
                vec![
                    (START, "bid", "233.61", "10", "2336.10"),
                    (START, "ask", "233.63", "12", "2803.56"),
                    (START + 1, "bid", "233.61", "4", "934.44"),
                    (START + 1, "ask", "233.63", "0", "0"),
                    (START + 1, "ask", "233.64", "8", "1869.12"),
                ]
            };
            let mut expected: Vec<_> = expected
                .into_iter()
                .map(|(time, side, price, base, quote)| {
                    (
                        time,
                        side.to_owned(),
                        price.parse::<Decimal>().unwrap(),
                        base.parse::<Decimal>().unwrap(),
                        quote.parse::<Decimal>().unwrap(),
                    )
                })
                .collect();
            rows.sort();
            expected.sort();
            if rows != expected {
                return Err(format!("{kind}: expected {expected:?}, got {rows:?}"));
            }
        }
        Ok(())
    })();
    run.finish(&result)?;
    result
}
